  top_p?: number;
}): Promise<CallToolResult>; };
```"},{"name":"mcp__local_llm__train_from_conversations","description":"Fine-tune a local model on the user's recent conversation history. EXPENSIVE: 30 min – 4 h depending on dataset size; locks the GPU exclusively for the run. First call without `confirm: true` returns the dataset estimate (conversation count + turn count) so the caller can decide. With `confirm: true`, shells out to the `blut` binary (BLUT — Brian Lam's Universal Trainer) in detached background mode and returns immediately — check `blut jobs` for the resulting job id. The MCP server does NOT depend on blut; the binary must be installed separately (cargo install --path lamu-rs/blut) or located via $BLUT_BIN. ($LAMU_TRAIN_BIN remains accepted as a back-compat alias.)

exec tool declaration:
```ts
declare const tools: { mcp__local_llm__train_from_conversations(args: {
  // HuggingFace base model id (org/name).
  base_model?: string;
  // Must be true to actually start. First call without confirm returns the dataset estimate so the caller can decide.
  confirm?: boolean;
  // Fine-tuning method. qlora is the 4090-friendly default.
  method?: "qlora" | "lora" | "full";
  // Registry name for the trained model. Must match [A-Za-z0-9_.-]+ with no leading '.' or '-' and no '..'.
  output_name: string;
  // How far back to pull conversations. Humantime duration: '7d', '30d', '12h', etc.
  since?: string;
}): Promise<CallToolResult>; };
```"},{"name":"mcp__local_llm__write_file","description":"Write a file with rollback journaling (Phase 6.1). Records the file's pre-state under session_id; `lamu rollback <session>` restores. Path is required relative to lamu-mcp's cwd; absolute paths and '..' segments are refused so the call cannot escape the working directory. session_id must match [A-Za-z0-9_-.]+ — anything else is rejected up front.

exec tool declaration:
```ts
declare const tools: { mcp__local_llm__write_file(args: {
  // UTF-8 file contents.
  content: string;
  // Path under cwd. Relative components only — '..' is refused.
  path: string;
  // Session identifier for rollback. Allowed chars: [A-Za-z0-9_-.]
  session_id: string;
}): Promise<CallToolResult>; };
```"}]

