  15	/// Re-attest concurrency evidence at the current base (ADR-0020 §4).
  16	///
  17	/// Nothing produced this artifact. `haqp_qualify.sh` had no concurrency stage
  18	/// and the justfile no recipe, so `concurrency.json` was hand-written once in
  19	/// August and every later lane inherited its stale `source_commit` -- the flip
  20	/// refused the 2026-09-01 campaign partly on this file. A required artifact
  21	/// with no producer cannot survive a rule that says evidence must describe ONE
  22	/// fixed tree.
  23	///
  24	/// The record is built from the packet and the closed constants
  25	/// `verify_concurrency_evidence_record` checks against, not by re-stamping the
  26	/// previous output: regenerating a file from itself would carry a wrong
  27	/// declaration forward untouched, which is the failure mode this replaces.
  28	pub fn run_concurrency_repo(root: &Utf8Path) -> Result<()> {
  29	    let packet = read_packet(root)?;
  30	    anyhow::ensure!(
  31	        packet.concurrent_code == "not_applicable",
  32	        "concurrency generation covers the not-applicable declaration only; \
  33	         packet declares {:?} and an executed schedule campaign must record its \
  34	         own runs",
  35	        packet.concurrent_code
  36	    );
  37	    let commit = git_text(root, &["rev-parse", "HEAD"])?;
  38	    let tree = git_text(root, &["rev-parse", "HEAD^{tree}"])?;
  39	    let evidence = ConcurrentEvidence {
  40	        schema_version: "haqp-concurrency-v1".to_owned(),
  41	        implementation: packet.concurrent_code.clone(),
  42	        mode: "not_applicable".to_owned(),
  43	        reason: "no concurrent implementation exists; deterministic schedule \
  44	                 exploration is reserved for Phase 6"
  45	            .to_owned(),
