2401	/// Bind each review row to a committed record (M17.5 pass-2 #20).
2402	///
2403	/// A review row was four self-asserted numbers with nothing behind them. The
2404	/// internal-consistency rules hold at every layer; the committed record is
2405	/// demanded only once a review claims `pass`, matching how
2406	/// `verify_generated_inventory` treats seeds and evidence hashes.
2407	fn verify_review_evidence(root: &Utf8Path, packet: &Packet) -> Result<()> {
2408	    let mut records: Vec<(String, ReviewRecord)> = Vec::new();
2409	    for review in &packet.reviews {
2410	        let raised = review.findings.iter().collect::<BTreeSet<_>>();
2411	        let unverified = review
2412	            .independently_reproduced
2413	            .iter()
2414	            .filter(|id| !raised.contains(id))
2415	            .collect::<Vec<_>>();
2416	        if !unverified.is_empty() {
2417	            anyhow::bail!(
2418	                "{} claims to have independently reproduced {unverified:?}, which it \
2419	                 never raised as findings",
2420	                review.reviewer
2421	            );
2422	        }
2423	        // A finding counted as VERIFIED and unresolved must be one that survived
2424	        // independent reproduction; otherwise "verified" means one model said so.
2425	        if review.unresolved_verified_findings > review.independently_reproduced.len() as u64 {
2426	            anyhow::bail!(
2427	                "{} counts {} unresolved VERIFIED findings but independently reproduced \
2428	                 only {} — a finding one reviewer asserted is not a verified finding \
2429	                 (ADR-0020 §6)",
2430	                review.reviewer,
2431	                review.unresolved_verified_findings,
2432	                review.independently_reproduced.len()
2433	            );
2434	        }
2435	        if review.result != "pass" {
2436	            continue;
2437	        }
2438	        let Some(evidence) = &review.evidence else {
2439	            anyhow::bail!(
2440	                "{} claims pass with no committed record; the lane's own output lives \
2441	                 under target/ and cannot be read back",
2442	                review.reviewer
2443	            );
2444	        };
2445	        // The packet is the very thing this verifier exists to distrust, so its
2446	        // paths are not taken on faith. `join` DISCARDS the base when handed an
2447	        // absolute path, so `evidence: "/etc/passwd"` would read straight out of
2448	        // the repository; `..` walks out just as effectively.
2449	        let candidate = Utf8Path::new(evidence);
2450	        if candidate.is_absolute()
2451	            || candidate
2452	                .components()
2453	                .any(|part| part == camino::Utf8Component::ParentDir)
2454	        {
2455	            anyhow::bail!(
2456	                "{} points its record at {evidence:?}, which escapes the repository; \
2457	                 evidence paths must be relative and contain no `..`",
2458	                review.reviewer
2459	            );
2460	        }
2461	        let path = root.join(candidate);
2462	        let canonical_root = fs::canonicalize(root.as_std_path())
2463	            .context("canonicalize repository root for review evidence")?;
2464	        let canonical_path = fs::canonicalize(&path).with_context(|| {
2465	            format!(
2466	                "{path}: {} claims pass but its record is missing",
2467	                review.reviewer
2468	            )
2469	        })?;
2470	        anyhow::ensure!(
2471	            canonical_path.starts_with(&canonical_root),
2472	            "{} review record resolves outside repository via symlink",
2473	            review.reviewer
2474	        );
2475	        let bytes = fs::read(&path).with_context(|| {
2476	            format!(
2477	                "{path}: {} claims pass but its record is missing",
2478	                review.reviewer
2479	            )
2480	        })?;
2481	        let record: ReviewRecord =
2482	            serde_json::from_slice(&bytes).with_context(|| format!("parse {path}"))?;
2483	        verify_review_record(root, review, &record, &path)?;
2484	        let provenance = packet
2485	            .provenance
2486	            .as_ref()
2487	            .context("qualified review evidence requires packet provenance")?;
2488	        require_eq(
2489	            "review record fixed_base.commit",
2490	            &record.fixed_base.commit,
2491	            &provenance.fixed_commit,
2492	        )?;
2493	        require_eq(
2494	            "review record fixed_base.tree",
2495	            &record.fixed_base.tree,
2496	            &provenance.fixed_tree,
2497	        )?;
2498	        anyhow::ensure!(
2499	            record.fixed_base.clean,
2500	            "{} review record was produced from a dirty fixed base",
2501	            review.reviewer
2502	        );
2503	        records.push((review.reviewer.clone(), record));
2504	    }
2505	    verify_reviewer_independence(&records)?;
2506	    verify_cross_pass_reproduction(&records)
2507	}
