3007	                    .provider_model
3008	                    .contains(record.reviewer.model_family.as_str())
3009	                    || record
3010	                        .reviewer
3011	                        .model_family
3012	                        .contains(receipt.provider_model.as_str()),
3013	                "the provider says {:?} answered and the record names {:?}",
3014	                receipt.provider_model,
3015	                record.reviewer.model_family
3016	            );
3017	            anyhow::ensure!(
3018	                receipt.created > 0,
3019	                "a mimo receipt must carry the provider's clock"
3020	            );
3021	            for key in ["prompt_tokens", "completion_tokens", "total_tokens"] {
3022	                anyhow::ensure!(
3023	                    receipt.usage.contains_key(key),
3024	                    "a mimo receipt must carry the provider's {key}; a changed usage envelope \
3025	                     must be seen here, not discovered later through a binding that moved"
3026	                );
3027	            }
3028	            let billed = receipt
3029	                .usage
3030	                .get("total_tokens")
3031	                .and_then(serde_json::Value::as_u64)
