2877	/// The receipt must be the backend's own shape, and a Codex transcript must be
2878	/// retained beside the record and hash to what the receipt claims (F-49).
2879	/// The last assistant message in a codex rollout: what the provider actually
2880	/// said, as its own transcript records it.
2881	fn transcript_final_message(bytes: &[u8]) -> Option<String> {
2882	    let mut spoken = None;
2883	    for line in std::str::from_utf8(bytes).ok()?.lines() {
2884	        let Ok(record) = serde_json::from_str::<serde_json::Value>(line) else {
2885	            continue;
2886	        };
2887	        let payload = &record["payload"];
2888	        if record["type"] != "response_item"
2889	            || payload["type"] != "message"
2890	            || payload["role"] != "assistant"
2891	        {
2892	            continue;
2893	        }
2894	        let text = payload["content"]
2895	            .as_array()?
2896	            .iter()
2897	            .filter_map(|part| part["text"].as_str())
2898	            .collect::<String>();
2899	        spoken = Some(text);
2900	    }
2901	    spoken
2902	}
