3079	/// The registry's commands are the project's own gates, run with the gate's
3080	/// environment and no timeout: they are what CI runs, so a hang here is a hang
3081	/// in CI, visible either way (review of `e490671`). The working directory is a
3082	/// disposable worktree at the commit the receipt names, never the live tree.
3083	fn verify_resolution_command_ran(
3084	    root: &Utf8Path,
3085	    who: &str,
3086	    evidence_text: &str,
3087	    commit: &str,
3088	) -> Result<()> {
3089	    let claimed = evidence_text
3090	        .lines()
3091	        .find_map(|line| line.trim_start().strip_prefix("verification_command:"))
3092	        .map(str::trim)
3093	        .unwrap_or_default();
3094	    let argv = RESOLUTION_COMMANDS
3095	        .iter()
3096	        .find(|(name, _)| *name == claimed)
3097	        .map(|(_, argv)| *argv)
3098	        .with_context(|| {
3099	            format!(
3100	                "{who}: resolution claims verification command {claimed:?}, which is not one the \
3101	                 gate can run; the registry is closed so a receipt cannot name a command that \
3102	                 exists only in its own text"
3103	            )
3104	        })?;
3105	    let (program, rest) = argv.split_first().context("registry command is empty")?;
3106	    // Blind pass 1 at aecb2ec7 (A12): the command ran against the working
3107	    // tree, so a receipt claiming a finding was resolved at some commit was
3108	    // answered by whether the command passes at HEAD. Reachability was
3109	    // checked and the commit then ignored. It runs in a disposable worktree
3110	    // checked out at the claimed commit now, which is what the receipt says.
3111	    let scratch = liminal_scratch::ScratchDir::new("haq-resolution-replay")?;
3112	    let worktree = scratch.path().to_owned();
3113	    let add = Command::new("git")
3114	        .current_dir(root)
3115	        .args(["worktree", "add", "--detach", "--quiet"])
3116	        .arg(&worktree)
3117	        .arg(commit)
3118	        .output()?;
3119	    anyhow::ensure!(
3120	        add.status.success(),
3121	        "{who}: resolution replay worktree add at {commit} failed: {}",
3122	        String::from_utf8_lossy(&add.stderr).trim()
3123	    );
3124	    let mut guard = WorktreeGuard::new(root, &worktree);
3125	    let status = Command::new(program)
3126	        .current_dir(&worktree)
3127	        .args(rest)
3128	        .status()
3129	        .with_context(|| format!("{who}: run resolution verification {claimed:?} at {commit}"))?;
3130	    guard.remove()?;
3131	    anyhow::ensure!(
3132	        status.success(),
3133	        "{who}: resolution claims {claimed:?} exited zero at {commit}; it exited {status}"
3134	    );
3135	    Ok(())
3136	}
