2509	/// A reviewer cannot make its own "independent reproduction" true by setting
2510	/// two booleans in one record. Every reproduced finding must have one matching
2511	/// verified defect in the other isolated pass, with the same attack class,
2512	/// exact source target, and identical falsification claim/observation. This
2513	/// prevents two semantically different reports at one line from becoming a
2514	/// concurrence by coordinate coincidence; finding IDs remain pass-local.
2515	/// Whether two blinded passes are reporting the same defect. Blind pass 1 at
2516	/// `0a0b4b4b` (A10): this required the `attempt` and `observed_result` strings
2517	/// to be byte-identical. Two reviewers who cannot see each other's work will
2518	/// not write the same sentence, so a genuine independent reproduction was
2519	/// rejected unless they coordinated wording — which is the one thing the
2520	/// blinding exists to prevent. The class and the coordinate already match by
2521	/// the time this is asked; what is left to establish is that the two are about
2522	/// the same thing, and shared vocabulary establishes it. Four significant
2523	/// words in common is far more than coincidence at one coordinate and far less
2524	/// than dictation.
2525	fn reports_the_same_defect(
2526	    left: &ReviewRecordAttempt,
2527	    right: &ReviewRecordAttempt,
2528	    corpus: &[&ReviewRecordAttempt],
2529	) -> bool {
2530	    // Blind pass 1 at `ec045588` (A02): both reports name the coordinate, so
2531	    // `crates`, `liminal`, `xtask` and `haq` were four shared words before
2532	    // either said anything — the coordinate matched twice, once as itself and
2533	    // once as vocabulary. Words the coordinate already carries are struck out,
2534	    // and so are the handful this campaign puts in every report.
2535	    const UBIQUITOUS: [&str; 8] = [
2536	        "verifier",
2537	        "verify",
2538	        "packet",
2539	        "evidence",
2540	        "check",
2541	        "checks",
2542	        "because",
2543	        "committed",
2544	    ];
2545	    let coordinate: BTreeSet<String> = format!("{} {}", left.target, right.target)
2546	        .to_ascii_lowercase()
2547	        .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2548	        .map(str::to_owned)
2549	        .collect();
2550	    let vocabulary = |attempt: &ReviewRecordAttempt| {
2551	        format!("{} {}", attempt.attempt, attempt.observed_result)
2552	            .to_ascii_lowercase()
2553	            .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2554	            .filter(|word| word.len() >= 4)
2555	            .filter(|word| !coordinate.contains(*word))
2556	            .filter(|word| !UBIQUITOUS.contains(word))
2557	            .map(str::to_owned)
2558	            .collect::<BTreeSet<_>>()
2559	    };
2560	    let shared: BTreeSet<String> = vocabulary(left)
2561	        .intersection(&vocabulary(right))
2562	        .cloned()
2563	        .collect();
2564	    if shared.len() < 4 {
2565	        return false;
2566	    }
2567	    // Blind pass 1 at `2bba9071` (A09): four shared words is a count, and a
2568	    // count is satisfied by four words this campaign puts in every report.
2569	    // What makes two reports the same report is sharing something RARE — a
2570	    // word that does not appear all over the rest of the record. Two such
2571	    // words, measured against every attempt in both passes rather than
2572	    // against a list someone maintains.
2573	    let distinctive = shared
2574	        .iter()
2575	        .filter(|word| {
2576	            corpus
2577	                .iter()
2578	                .filter(|attempt| {
2579	                    format!("{} {}", attempt.attempt, attempt.observed_result)
2580	                        .to_ascii_lowercase()
2581	                        .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2582	                        .any(|token| token == word.as_str())
2583	                })
2584	                .count()
2585	                <= 2
2586	        })
2587	        .count();
2588	    distinctive >= 2
2589	}
