2982	fn verify_review_provider_receipt(record: &ReviewRecord, record_path: &Utf8Path) -> Result<()> {
2983	    let receipt = &record.provider_receipt;
2984	    require_eq(
2985	        "review provider_receipt backend",
2986	        &receipt.backend,
2987	        &record.reviewer.backend,
2988	    )?;
2989	    match receipt.backend.as_str() {
2990	        "codex" => verify_codex_receipt(record, record_path),
2991	        "mimo-direct" => {
2992	            anyhow::ensure!(
2993	                !receipt.response_id.trim().is_empty(),
2994	                "a mimo receipt must carry the provider's response id"
2995	            );
2996	            // Blind pass 1 at `3720d179` (A10): non-empty was the whole
2997	            // check, so the provider could say it answered as anything and
2998	            // the record's own `model_family` went uncompared. The receipt is
2999	            // the provider's statement of who answered; if it does not name
3000	            // the reviewer the record claims, one of the two is wrong.
