  2879	/// The last assistant message in a codex rollout: what the provider actually
  2880	/// said, as its own transcript records it.
  2881	fn transcript_final_message(bytes: &[u8]) -> Option<String> {
  2882	    let mut spoken = None;
  2883	    for line in std::str::from_utf8(bytes).ok()?.lines() {
  2884	        let Ok(record) = serde_json::from_str::<serde_json::Value>(line) else {
  2885	            continue;
  2886	        };
