  3067	/// from a closed registry rather than run as written: executing arbitrary text
  3068	/// out of an evidence file would hand whoever wrote the file this process.
  3069	const RESOLUTION_COMMANDS: [(&str, &[&str]); 4] = [
  3070	    ("just ci", &["just", "ci"]),
  3071	    ("just haq-inventory", &["just", "haq-inventory"]),
  3072	    ("just haq-canaries", &["just", "haq-canaries"]),
  3073	    (
