  2904	/// A codex receipt: the session it names, the transcript it retained, and
  2905	/// that the answer beside the record is the one the transcript records the
  2906	/// provider giving.
  2907	fn verify_codex_receipt(record: &ReviewRecord, record_path: &Utf8Path) -> Result<()> {
  2908	    let receipt = &record.provider_receipt;
  2909	    anyhow::ensure!(
  2910	        !receipt.session_id.trim().is_empty() && !receipt.session_file.trim().is_empty(),
  2911	        "a codex receipt must name the session that answered"
  2912	    );
  2913	    require_hex_digest("review transcript_sha256", &receipt.transcript_sha256)?;
  2914	    let transcript = record_path.with_extension("session.jsonl");
  2915	    let bytes = fs::read(&transcript).with_context(|| {
  2916	        format!("{transcript}: the codex transcript must be retained beside its record")
  2917	    })?;
  2918	    anyhow::ensure!(
  2919	        bytes.len() as u64 == receipt.transcript_bytes,
  2920	        "codex transcript is {} bytes, receipt claims {}",
  2921	        bytes.len(),
  2922	        receipt.transcript_bytes
  2923	    );
  2924	    require_eq(
  2925	        "review transcript_sha256 (of the retained transcript)",
  2926	        &format!("{:x}", Sha256::digest(&bytes)),
  2927	        &receipt.transcript_sha256,
  2928	    )?;
  2929	    // Blind pass 1 at `aeed70f9` (A09): the transcript's bytes were
  2930	    // authenticated and its IDENTITY was not — `session_id` and
  2931	    // `session_file` only had to be non-empty, so a record could name
  2932	    // one session and retain another's rollout. A rollout opens with
  2933	    // its own `session_meta`, and the receipt's id ends with the UUID
  2934	    // that record carries.
  2935	    let first = std::str::from_utf8(&bytes)
  2936	        .context("codex transcript is not UTF-8")?
  2937	        .lines()
  2938	        .next()
  2939	        .context("codex transcript is empty")?;
  2940	    let meta: serde_json::Value =
  2941	        serde_json::from_str(first).context("codex transcript's first record is not JSON")?;
  2942	    anyhow::ensure!(
  2943	        meta["type"] == "session_meta",
  2944	        "a codex rollout opens with session_meta; this one opens with {:?}",
  2945	        meta["type"]
  2946	    );
  2947	    let declared = meta["payload"]["session_id"]
  2948	        .as_str()
  2949	        .context("codex session_meta carries no session_id")?;
  2950	    // Codex names a rollout `<timestamp>-<uuid>` and its `session_meta`
  2951	    // carries the bare uuid, so the receipt's id either IS the declared
  2952	    // id or ends with it after a separator. Review of `bba803d4`: a
  2953	    // bare `ends_with` would also accept `xfixture` for `fixture`,
  2954	    // which is a different session.
  2955	    anyhow::ensure!(
  2956	        receipt.session_id == declared || receipt.session_id.ends_with(&format!("-{declared}")),
  2957	        "receipt names session {:?}, retained transcript is session {declared:?}",
  2958	        receipt.session_id
  2959	    );
  2960	    require_eq(
  2961	        "review provider_receipt session_file",
  2962	        &receipt.session_file,
  2963	        &format!("rollout-{}.jsonl", receipt.session_id),
  2964	    )?;
  2965	    // Blind pass 1 at `3720d179` (A09): the raw answer and the
  2966	    // transcript were each hashed and neither was checked against the
  2967	    // other, so a record could retain a real session and a different
  2968	    // answer — both digests true, the pair a fiction. The rollout's
  2969	    // last assistant message IS the answer the runner saved.
  2970	    let raw_path = record_path.with_extension("raw.txt");
  2971	    let raw = fs::read_to_string(&raw_path)
  2972	        .with_context(|| format!("{raw_path}: the raw answer must be retained"))?;
  2973	    let spoken = transcript_final_message(&bytes)
  2974	        .with_context(|| format!("{transcript}: the transcript carries no assistant message"))?;
  2975	    anyhow::ensure!(
  2976	        spoken.trim() == raw.trim(),
  2977	        "the retained answer is not the one the transcript records the provider giving"
  2978	    );
