9250	/// Whether a mutant is GOOD is the 1b runner's question.
9251	/// The aliases a `use` line introduces for the symbols it imports:
9252	/// `use std::fs::{rename as mv, remove_file};` yields `("rename", "mv")`.
9253	/// Blind-review follow-up (review of c455cdf): splitting the whole line on
9254	/// `" as "` mangled a brace group into an alias like `mv, remove_file}`, which
9255	/// matched nothing and reopened the evasion the alias scan closed.
9256	/// `line` with a leading item visibility removed: `pub`, `pub(crate)`,
9257	/// `pub(super)`, `pub(in crate::x)`. Unchanged when it carries none, and
9258	/// unchanged for an identifier that merely starts with those letters.
9259	fn without_visibility(line: &str) -> &str {
9260	    let trimmed = line.trim();
9261	    let Some(rest) = trimmed.strip_prefix("pub") else {
9262	        return trimmed;
9263	    };
9264	    let rest = if let Some(open) = rest.strip_prefix('(') {
9265	        match open.find(')') {
9266	            Some(close) => &open[close + 1..],
9267	            None => return trimmed,
9268	        }
9269	    } else {
9270	        rest
9271	    };
9272	    if rest.starts_with(char::is_whitespace) {
9273	        rest.trim_start()
9274	    } else {
9275	        trimmed
9276	    }
9277	}
