9279	fn use_aliases(line: &str) -> Vec<(String, String)> {
9280	    // Blind pass 1 at ee646f8c (A10, A11): `pub use x::y as z;` is a `use`
9281	    // with a visibility in front, and stripping only `use ` meant the alias
9282	    // bound nothing — in the oracle's independence scan and in the durable
9283	    // transition census, which share this parser.
9284	    let Some(rest) = without_visibility(line).strip_prefix("use ") else {
9285	        return Vec::new();
9286	    };
9287	    // Braces are dropped rather than parsed, so a nested group
9288	    // (`use a::{b::{c as d}};`) reads the same as a flat one: what matters is
9289	    // the trailing `symbol as alias`, and the path before it is only used for
9290	    // its last segment (review of d09978c).
9291	    let flattened = rest.trim_end_matches(';').replace(['{', '}'], "");
9292	    let items = flattened.split(',').map(str::trim).collect::<Vec<_>>();
9293	    items
9294	        .iter()
9295	        .filter_map(|item| {
9296	            // Blind pass 1 at `3720d179` (A02): only a renaming `use` was
9297	            // read, so `use liminal_source::paragraph::parse;` — which brings
9298	            // the forbidden symbol in under its own last segment — bound
9299	            // nothing, and the oracle could call a bare `parse(`. An
9300	            // unaliased import aliases the symbol to its own final segment.
9301	            let (path, alias) = item
9302	                .split_once(" as ")
9303	                .unwrap_or_else(|| (item, item.rsplit("::").next().unwrap_or(item)));
9304	            // An import list's trailing comma leaves an empty item, whose
9305	            // "alias" would be the empty string — and `format!("{alias}(")`
9306	            // is then `(`, which every call in the file contains.
9307	            let alias = alias.trim();
9308	            if alias.is_empty() || !alias.chars().all(|ch| ch.is_alphanumeric() || ch == '_') {
9309	                return None;
9310	            }
9311	            // `rsplit` always yields at least one element.
9312	            let symbol = path
9313	                .rsplit("::")
9314	                .next()
9315	                .unwrap_or_default()
9316	                .trim()
9317	                .to_owned();
9318	            let alias = alias.trim().to_owned();
9319	            (alias != "_").then_some((symbol, alias))
9320	        })
9321	        .collect()
9322	}
