1631	/// parse: presence, ranges, classification and the hash relation. Returns the
1632	/// classifications and hashes so the case witness binds them.
1633	fn verify_coarse_scan(
1634	    source: &str,
1635	    coarse: &liminal_cst::CstDocument,
1636	) -> Result<(Vec<&'static str>, Vec<String>)> {
1637	    // The coarse scan is judged against the source directly, never against
1638	    // the fine parse: a document with a non-blank line has at least one block,
1639	    // every block's range lies inside the source and holds no blank line, and
1640	    // the blocks do not overlap (A01).
1641	    anyhow::ensure!(
1642	        coarse.source == source,
1643	        "coarse_parse changed the source it was given"
1644	    );
1645	    let has_content = source.lines().any(|line| !line.trim().is_empty());
1646	    anyhow::ensure!(
1647	        has_content != coarse.blocks.is_empty(),
1648	        "coarse_parse found {} blocks for a document that {} content",
1649	        coarse.blocks.len(),
1650	        if has_content { "has" } else { "has no" }
1651	    );
1652	    let mut previous_end = 0usize;
1653	    let mut kinds = Vec::new();
1654	    let mut hashes = Vec::new();
1655	    let mut by_text: BTreeMap<&str, String> = BTreeMap::new();
1656	    let mut by_hash: BTreeMap<String, &str> = BTreeMap::new();
1657	    for block in &coarse.blocks {
1658	        let start = usize::try_from(block.range.start).unwrap_or(usize::MAX);
1659	        let end = usize::try_from(block.range.end).unwrap_or(usize::MAX);
1660	        anyhow::ensure!(
1661	            start < end && end <= source.len() && start >= previous_end,
1662	            "coarse block {start}..{end} is empty, out of range, or overlaps its predecessor"
1663	        );
1664	        anyhow::ensure!(
1665	            source
1666	                .get(start..end)
1667	                .is_some_and(|text| text.lines().any(|line| !line.trim().is_empty())),
1668	            "coarse block {start}..{end} holds no content"
1669	        );
1670	        // Blind pass 1 at c29bc0ea (A01): the scan's ranges were judged and
1671	        // its classification was not, so `coarse_parse` could label every
1672	        // block alike and no generated case would notice. The kind is
1673	        // re-derived from the block's own first line, never read back from
1674	        // the production classifier ADR-0020 §5 forbids this oracle to reach.
1675	        // What this catches is the classifier drifting from its rule — a
1676	        // mutation, a reordered branch, a dropped case. It cannot catch the
1677	        // rule itself being wrong, because the rule is what it restates.
1678	        let text = source.get(start..end).unwrap_or_default();
1679	        let first = text.lines().next().unwrap_or_default().trim_start();
1680	        let hash_marks = first.chars().take_while(|ch| *ch == '#').count();
1681	        let expected = if first.starts_with("```") {
1682	            "fence"
1683	        } else if hash_marks > 0 && first[hash_marks..].starts_with(' ') {
1684	            "heading"
1685	        } else if first.starts_with("- ") || first.starts_with("* ") {
1686	            "list"
1687	        } else if first.starts_with('@') {
1688	            "directive"
1689	        } else if first.starts_with("![") || first.contains("](") {
1690	            "resource-reference"
1691	        } else {
