2006	/// Independent repair oracle. It checks the declared edge set against the
2007	/// returned order and records that permutation of input edges is stable.
2008	fn independent_oracle_source_repair(
2009	    order: &[liminal_id::RepairStepId],
2010	    ids: &[liminal_id::RepairStepId],
2011	    edges: &[(usize, usize)],
2012	    permuted_order: &[liminal_id::RepairStepId],
2013	) -> Result<Vec<u8>> {
2014	    let position: BTreeMap<liminal_id::RepairStepId, usize> = order
2015	        .iter()
2016	        .enumerate()
2017	        .map(|(index, id)| (*id, index))
2018	        .collect();
2019	    // Blind pass 1 at f360e90 (A03): equal length let a duplicated step stand
2020	    // in for a missing one. The order is exactly the declared steps, once each.
2021	    let mut declared = ids.to_vec();
2022	    let mut returned = order.to_vec();
2023	    declared.sort_unstable();
2024	    returned.sort_unstable();
2025	    anyhow::ensure!(
2026	        declared == returned && declared.windows(2).all(|pair| pair[0] != pair[1]),
2027	        "ordering dropped, duplicated or invented steps"
2028	    );
2029	    for (before, after) in edges {
2030	        anyhow::ensure!(
2031	            position[&ids[*before]] < position[&ids[*after]],
2032	            "ordering violated a declared dependency"
2033	        );
2034	    }
2035	    anyhow::ensure!(
2036	        permuted_order == order,
2037	        "topological order changed under permutation of dependency edges"
2038	    );
2039	    Ok(order
2040	        .iter()
2041	        .flat_map(|id| id.as_uuid().into_bytes())
2042	        .collect())
2043	}
