1788	fn independent_oracle_source_cst(
1789	    source: &str,
1790	    emitted: &str,
1791	    once: &str,
1792	    twice: &str,
1793	    content: &str,
1794	    coarse: &liminal_cst::CstDocument,
1795	) -> Result<Vec<u8>> {
1796	    anyhow::ensure!(emitted == source, "CST emit is not lossless for {source:?}");
1797	    anyhow::ensure!(once == twice, "formatting is not idempotent");
1798	    // Blind pass 1 at 5fb1b57 (A01): those two say nothing about whether
1799	    // formatting KEPT the document. A formatter returning a constant is
1800	    // idempotent, and the lossless check never touches the formatter at all.
1801	    // The generated word is content, not layout: formatting may move it, never
1802	    // lose it. A durable-marker set would be the natural check and is nearly
1803	    // vacuous for this corpus, where only the malformed categories carry `{#`.
1804	    // Alphanumeric runs, not the raw token: a generated word can begin with
1805	    // markdown syntax (`- v`), and lowering `- ` into list structure is the
1806	    // formatter doing its job, not losing content.
1807	    // Blind pass 1 at 91b54842 (A01): the runs were filtered to three
1808	    // characters and up. `Rng::word` draws one to twelve characters from an
1809	    // alphabet holding `-`, `_` and a space, so `a`, `x y` and `a-b` are all
1810	    // reachable tokens with no run that long — for those the survival check
1811	    // had nothing to check and a formatter could drop the content outright.
1812	    // Every non-empty run counts now. The dialect numbers nothing (an ordered
1813	    // block is the keyword `ordered`, never `1.`), so no digit legitimately
1814	    // disappears, and a one-character run is weak rather than false: it fires
1815	    // only when that character is absent from the whole output.
1816	    let words = |text: &str| {
1817	        text.split(|ch: char| !ch.is_alphanumeric())
1818	            .filter(|run| !run.is_empty())
1819	            .map(str::to_owned)
1820	            .collect::<BTreeSet<_>>()
1821	    };
1822	    let lost = words(content)
1823	        .into_iter()
1824	        .filter(|word| source.contains(word.as_str()) && !once.contains(word.as_str()))
1825	        .collect::<Vec<_>>();
1826	    // Blind pass 1 at `6b36bbb9` (A09): survival was judged on alphanumeric
1827	    // runs, so content that is punctuation raised nothing — a token of `_`
1828	    // has no run at all and could be dropped in silence. A character is
1829	    // markup only if the dialect lowers it: `-`, `*`, `#`, `>`, `|`, `+` and
1830	    // a backtick begin lists, headings, quotes, tables and fences, and
1831	    // lowering those is the formatter doing its job. Everything else that is
1832	    // not whitespace is content and must come back.
1833	    let lost_marks = content
1834	        .chars()
1835	        .filter(|ch| {
1836	            !ch.is_whitespace()
1837	                && !ch.is_alphanumeric()
1838	                && !STRUCTURAL_MARKUP.contains(ch)
1839	                && source.contains(*ch)
1840	                && !once.contains(*ch)
1841	        })
1842	        .collect::<BTreeSet<_>>();
1843	    anyhow::ensure!(
1844	        lost_marks.is_empty(),
1845	        "formatting dropped the document's punctuation content {lost_marks:?}: {source:?} -> \
1846	         {once:?}"
1847	    );
1848	    anyhow::ensure!(
1849	        lost.is_empty(),
1850	        "formatting dropped the document's content {lost:?}: {source:?} -> {once:?}"
1851	    );
1852	    // Blind pass 1 at `0a0b4b4b` (A01): membership was checked and ORDER was
1853	    // not, so a formatter that scrambled a document's words kept every word,
1854	    // every mark, non-emptiness and idempotence, and lost the meaning. A
1855	    // formatter may move a word between lines; it may never move one past
1856	    // another, so the sequence of alphanumeric runs is invariant.
1857	    // Formatting may ADD words — the explicit dialect wraps content in `node`,
1858	    // `paragraph`, `literal` — so the source's words must appear in the output
1859	    // in their own order, not as the whole of it.
1860	    let emitted_words = sequence(once);
1861	    let source_words = sequence(source);
1862	    let mut next = emitted_words.iter();
1863	    if !source_words
1864	        .iter()
1865	        .all(|word| next.any(|candidate| candidate == word))
1866	    {
1867	        // Review of `ec045588`: a subsequence fails for two different reasons
1868	        // and they are not the same defect. If some word appears fewer times
1869	        // in the output than in the source, the formatter dropped a copy —
1870	        // which the loss check above cannot see, because it asks whether the
1871	        // word survives at all and not how often. Otherwise every word is
1872	        // present the right number of times and the order changed.
1873	        let count = |words: &[String], word: &String| words.iter().filter(|w| *w == word).count();
1874	        let dropped = source_words
1875	            .iter()
1876	            .find(|word| count(&source_words, word) > count(&emitted_words, word));
1877	        anyhow::ensure!(
1878	            dropped.is_none(),
1879	            "formatting dropped a copy of {:?}: {source:?} -> {once:?}",
1880	            dropped.expect("checked")
1881	        );
1882	        anyhow::bail!("formatting reordered the document's words: {source:?} -> {once:?}");
1883	    }
1884	    anyhow::ensure!(
1885	        source.trim().is_empty() || !once.trim().is_empty(),
1886	        "formatting emptied a non-empty document"
1887	    );
1888	    let (kinds, hashes) = verify_coarse_scan(source, coarse)?;
1889	    let mut witness = emitted.as_bytes().to_vec();
1890	    witness.extend_from_slice(once.as_bytes());
1891	    witness.extend_from_slice(format!("coarse:{}", coarse.blocks.len()).as_bytes());
1892	    witness.extend_from_slice(kinds.join(",").as_bytes());
1893	    witness.extend_from_slice(hashes.join(",").as_bytes());
1894	    Ok(witness)
1895	}
