1897	/// Independent merge oracle. It checks raw content and outcome classes, not
1898	/// merge-result equality.
1899	fn independent_oracle_source_transform(
1900	    base: &str,
1901	    ours: &str,
1902	    identity: &liminal_source::merge::MergeOutcome,
1903	    forward: &liminal_source::merge::MergeOutcome,
1904	    swapped: &liminal_source::merge::MergeOutcome,
1905	) -> Result<Vec<u8>> {
1906	    let liminal_source::merge::MergeOutcome::Disjoint { merged } = identity else {
1907	        anyhow::bail!("identity merge reported non-disjoint outcome: {identity:?}");
1908	    };
1909	    let merged_tokens = merged.split_whitespace().collect::<Vec<_>>();
1910	    let ours_tokens = ours.split_whitespace().collect::<Vec<_>>();
1911	    let mut merged_multiset = merged_tokens.clone();
1912	    let mut ours_multiset = ours_tokens.clone();
1913	    merged_multiset.sort_unstable();
1914	    ours_multiset.sort_unstable();
1915	    anyhow::ensure!(
1916	        ours_multiset == merged_multiset,
1917	        "identity merge dropped content: {ours:?} -> {merged:?}"
1918	    );
1919	    // Token multisets alone permit an implementation to drop or duplicate
1920	    // durable markers. The merge contract keeps base slot order as its primary
1921	    // layout; a pure move is therefore intentionally not an order-preserving
1922	    // relation, but its marker set must still survive exactly.
1923	    let marker_order = |text: &str| {
1924	        text.split_whitespace()
1925	            .filter(|token| token.starts_with("{#") && token.ends_with('}'))
1926	            .map(str::to_owned)
1927	            .collect::<Vec<_>>()
1928	    };
1929	    let base_markers = marker_order(base);
1930	    let ours_markers = marker_order(ours);
1931	    if ours_markers != base_markers {
1932	        let mut expected = ours_markers.clone();
1933	        let mut actual = marker_order(merged);
1934	        expected.sort_unstable();
1935	        actual.sort_unstable();
1936	        anyhow::ensure!(
1937	            actual == expected,
1938	            "identity merge changed durable marker set under layout normalization"
1939	        );
1940	        // Blind pass 1 at 612cbcc (A02): the marker SET surviving a move said
1941	        // nothing about which content each marker kept; swapping the contents
1942	        // of two moved markers passed. A move keeps every marker's content.
1943	        let markered = |text: &str| {
1944	            ordered_block_contents(text)
1945	                .into_iter()
1946	                .filter(|(marker, _)| marker.starts_with("{#"))
1947	                .collect::<BTreeMap<_, _>>()
1948	        };
1949	        anyhow::ensure!(
1950	            markered(merged) == markered(ours),
1951	            "identity merge re-associated content across moved markers: {ours:?} -> {merged:?}"
1952	        );
1953	    }
1954	    if ours_markers == base_markers {
1955	        anyhow::ensure!(
1956	            marker_order(merged) == ours_markers,
1957	            "identity merge reordered durable markers"
1958	        );
1959	        anyhow::ensure!(
1960	            ordered_block_contents(merged) == ordered_block_contents(ours),
1961	            "identity merge reordered ordinary content: {ours:?} -> {merged:?}"
1962	        );
1963	    }
1964	    let disjoint = |outcome: &liminal_source::merge::MergeOutcome| {
1965	        matches!(
1966	            outcome,
1967	            liminal_source::merge::MergeOutcome::Disjoint { .. }
1968	        )
1969	    };
1970	    anyhow::ensure!(
1971	        disjoint(forward) == disjoint(swapped),
1972	        "merge disjointness is not symmetric under swapping sides"
1973	    );
1974	    Ok(format!("{identity:?}|{forward:?}|{swapped:?}").into_bytes())
1975	}
