8715	fn authoritative_requirement_map()
8716	-> BTreeMap<&'static str, (&'static str, &'static str, bool, bool)> {
8717	    AUTHORITATIVE_REQUIREMENTS
8718	        .iter()
8719	        .map(|(id, kind, source, critical, stateful)| (*id, (*kind, *source, *critical, *stateful)))
8720	        .collect()
