8794	/// Closed digest over test identity, executable name, requirement mapping, and
8795	/// evidence kinds. Existence checks alone let a packet remap broad, unrelated
8796	/// test names to satisfy coverage; this registry makes the authoritative
8797	/// mapping tamper-evident (P1-A04). Recompute with the canonical NUL/US stream
8798	/// below and update this constant in the same commit as any test inventory edit.
8799	const TEST_REGISTRY_SHA256: &str =
8800	    "7a29add0e81657e17786934010638abf1ea99dfee4e162921a9ef2699197d447";
8801	
8802	fn verify_test_registry(packet: &Packet) -> Result<()> {
8803	    let mut canonical = String::new();
8804	    for test in &packet.tests {
8805	        canonical.push_str(&test.id);
8806	        canonical.push('\0');
8807	        canonical.push_str(&test.name);
8808	        canonical.push('\0');
8809	        canonical.push_str(&test.requirements.join("\x1f"));
8810	        canonical.push('\0');
8811	        canonical.push_str(&test.evidence.join("\x1f"));
8812	        canonical.push('\0');
8813	    }
8814	    let digest = sha256_text(&canonical);
8815	    anyhow::ensure!(
8816	        digest == TEST_REGISTRY_SHA256,
8817	        "test registry digest differs from closed authority: got {digest}, expected {TEST_REGISTRY_SHA256}"
8818	    );
8819	    Ok(())
8820	}
