8723	/// Evidence kinds every applicable critical requirement must carry
8724	/// (ADR-0020 §2: "positive, negative, malformed/adversarial, basis/provenance,
8725	/// and deterministic-replay evidence").
8726	const CORE_EVIDENCE: [&str; 5] = ["positive", "negative", "malformed", "basis", "replay"];
8727	/// "Stateful laws also have injected-fault and idempotent-recovery evidence."
8728	const STATEFUL_EVIDENCE: [&str; 2] = ["fault", "recovery"];
8729	/// Requirement kinds are closed by the HAQP packet contract. An open kind
8730	/// vocabulary lets a packet relabel a stateful requirement and evade its
8731	/// fault/recovery evidence obligations (M17.5 P1-A04).
8732	const REQUIREMENT_KINDS: [&str; 4] = ["law", "gate", "fault", "abuse"];
8733	/// Current packet's stateful law is M20 D20.3. Keep the semantic coordinate
8734	/// closed even if an attacker relabels its `kind` or drops its JSON marker.
8735	const STATEFUL_REQUIREMENT_IDS: [&str; 1] = ["P1-R015"];
8736	/// No single test may carry more than this share of the mutation denominator.
8737	const MAX_KILL_SHARE: f64 = 0.25;
8738	
8739	/// M17.5 F-05: a requirement mapped to one coarse end-to-end test is not
8740	/// covered. Every critical requirement must carry all five core evidence
8741	/// kinds, and fault-class requirements must additionally carry injected-fault
8742	/// and idempotent-recovery evidence.
8743	fn verify_evidence_coverage(packet: &Packet) -> Result<()> {
8744	    let known = CORE_EVIDENCE
8745	        .iter()
8746	        .chain(STATEFUL_EVIDENCE.iter())
8747	        .copied()
8748	        .collect::<BTreeSet<_>>();
8749	    let mut covered = BTreeMap::<&str, BTreeSet<&str>>::new();
8750	    for test in &packet.tests {
8751	        if test.evidence.is_empty() {
8752	            anyhow::bail!("{} declares no evidence kind", test.id);
8753	        }
8754	        for kind in &test.evidence {
8755	            if !known.contains(kind.as_str()) {
8756	                anyhow::bail!("{} declares unknown evidence kind {kind}", test.id);
8757	            }
8758	        }
8759	        for requirement in &test.requirements {
8760	            covered
8761	                .entry(requirement.as_str())
8762	                .or_default()
8763	                .extend(test.evidence.iter().map(String::as_str));
8764	        }
8765	    }
8766	    for requirement in &packet.requirements {
8767	        if !requirement.critical {
8768	            continue;
8769	        }
8770	        let have = covered
8771	            .get(requirement.id.as_str())
8772	            .cloned()
8773	            .unwrap_or_default();
8774	        let mut needed = CORE_EVIDENCE.to_vec();
8775	        if requirement.stateful || requirement.kind == "fault" {
8776	            needed.extend_from_slice(&STATEFUL_EVIDENCE);
8777	        }
8778	        let missing = needed
8779	            .into_iter()
8780	            .filter(|kind| !have.contains(kind))
8781	            .collect::<Vec<_>>();
8782	        if !missing.is_empty() {
8783	            anyhow::bail!(
8784	                "critical requirement {} ({}) is missing {} evidence",
8785	                requirement.id,
8786	                requirement.kind,
