9736	        locked.is_dir(),
9737	        "{locked} is missing: the locked corpus cannot be shown untouched when it is not there"
9738	    );
9739	    // The identities are the HELD-OUT corpus's, not the whole corpora tree's,
9740	    // so a hard link from `heldout` into a sibling corpus is an alias too — it
9741	    // would let a read of that sibling touch held-out bytes while every path
9742	    // involved looks legitimate.
9743	    let identities = locked_corpus_identities(root, "conformance/corpora/heldout")?;
9744	    let canonical = fs::canonicalize(&locked)
9745	        .with_context(|| format!("{locked}: locked corpus must resolve"))?;
9746	    let mut aliases = Vec::new();
9747	    let mut stack = vec![root.to_owned()];
9748	    while let Some(dir) = stack.pop() {
