9880	                .checked_sub(1)
9881	                .and_then(|prev| chars.get(prev))
9882	                .is_some_and(|prev| prev.is_alphanumeric() || *prev == '_')
9883	    });
9884	    let integer = chars.iter().enumerate().any(|(index, ch)| {
9885	        ch.is_ascii_digit()
9886	            && !index
9887	                .checked_sub(1)
9888	                .and_then(|prev| chars.get(prev))
9889	                .is_some_and(|prev| prev.is_alphanumeric() || *prev == '_')
9890	    });
