11294	fn durable_transition_sites(root: &Utf8Path) -> Result<BTreeMap<String, usize>> {
11295	    // Blind pass 1 at 612cbcc (A05): `inner.log.append(` is the store's durable
11296	    // append (P1-M022 deletes it) and was outside the census, so an append-based
11297	    // transition could move without the scope disclosure noticing.
11298	    // Blind pass 1 at f360e90 (A05): a direct `fs::rename` or `sync_all` is a
11299	    // durable transition with no marker call around it, so it escaped.
11300	    // Blind pass 1 at aa00d41 (A05): `use std::fs::rename as mv; mv(a, b)`
11301	    // named no marker. The durable symbols are matched by name, and a `use`
11302	    // that renames one adds its alias for that file.
11303	    const DURABLE_SYMBOLS: [&str; 6] = [
11304	        "commit",
11305	        "commit_if",
11306	        "append",
11307	        "sync_all",
11308	        "sync_data",
11309	        "rename",
11310	    ];
11311	    let listed = git_text(root, &["ls-files", "-z", "--", "crates"])?;
11312	    let mut sites = BTreeMap::new();
11313	    for name in listed.split('\0').filter(|name| !name.trim().is_empty()) {
11314	        if Utf8Path::new(name).extension() != Some("rs")
11315	            || name.starts_with("crates/liminal-xtask/")
11316	            || name.contains("/tests/")
11317	        {
11318	            continue;
11319	        }
11320	        let path = root.join(name);
11321	        // Never skip a tracked file we cannot read. Dropping it would delete
11322	        // its transitions from the measured surface, and the disclosure would
11323	        // then pass by describing a tree nobody managed to look at — the exact
11324	        // vacuity this check exists to prevent.
11325	        let text = fs::read_to_string(&path).with_context(|| {
11326	            format!(
11327	                "{name} is tracked but unreadable; the durable surface cannot be measured, and \
11328	                 a scope claim over a surface that was not read is worth nothing"
11329	            )
11330	        })?;
11331	        // A `use` that renames a durable symbol makes the alias a marker in
11332	        // this file: `use std::fs::rename as mv;` means `mv` is a rename.
11333	        let mut markers = DURABLE_SYMBOLS
11334	            .iter()
11335	            .map(|symbol| (*symbol).to_owned())
11336	            .collect::<Vec<_>>();
11337	        for line in text.lines() {
11338	            for (symbol, alias) in use_aliases(line) {
11339	                if DURABLE_SYMBOLS.contains(&symbol.as_str()) {
11340	                    markers.push(alias);
11341	                }
11342	            }
11343	        }
11344	        let count = text
11345	            .lines()
11346	            // An import declares a name; it performs no transition. Without
11347	            // this the aliasing `use` line counts as a durable call itself.
11348	            .filter(|line| {
11349	                let trimmed = line.trim_start();
11350	                !trimmed.starts_with("//") && !trimmed.starts_with("use ")
11351	            })
11352	            .map(|line| durable_symbol_hits(line, &markers))
11353	            .sum::<usize>();
11354	        if count > 0 {
11355	            sites.insert(name.to_owned(), count);
11356	        }
11357	    }
11358	    Ok(sites)
11359	}
