  834	            // disposition is stage-dependent. Hardcoding `killed` here made
  835	            // HAQP-1a UNREACHABLE: leave mutants `predeclared` and this gate
  836	            // failed; mark one `killed` and verify_qualification_stage failed.
  837	            // The first version of ADR-0021 shipped with exactly that
  838	            // contradiction — the deadlock it existed to break, reintroduced
  839	            // one layer down.
  840	            mutant: if packet.qualification_stage == "1b" {
  841	                "resolved"
  842	            } else {
  843	                "predeclared"
  844	            },
  845	            canary: "caught",
  846	            generated: "pass",
  847	            crash: "pass",
  848	            review: "pass",
  849	        },
