11219	/// Durable-transition call sites in tracked runtime source, by path.
11220	///
11221	/// Markers are call-shaped for the reason F-34 established for the
11222	/// `skipped-durable-transition` operator: a durable transition is a CALL, and
11223	/// matching bare words lets a rename satisfy the check.
11224	///
11225	/// Enumerated from `git ls-files`, never the filesystem (F-32): a scan that
11226	/// reads the working directory reports a different durable surface on a dirty
11227	/// tree than a fresh clone does, and the clone is the one that has to reproduce
11228	/// this.
11229	///
11230	/// `liminal-xtask` is excluded — the verifier is not runtime code, and its
11231	/// operator table contains the marker as a string literal, so including it
11232	/// would make this count self-referential. `tests/` is excluded: an integration
11233	/// test's commit is not a transition the product performs.
11234	///
11235	/// This is a TRIPWIRE, not a semantic census. It counts call sites textually,
11236	/// including any inside `#[cfg(test)]` modules, and its only job is to fail
11237	/// loudly when the durable surface moves under a disclosure that claims to have
11238	/// surveyed it.
11239	///
11240	/// Known imprecision, and its direction: line comments (`//`, and `///` with
11241	/// them) are skipped, but a marker inside a block comment or a string literal
11242	/// still counts. That errs toward REJECTION — a spurious match fails a packet
11243	/// that was honest, which a human then corrects. The opposite error, silently
11244	/// undercounting, would let a real durable transition hide, so the bias is the
11245	/// one worth having.
11246	/// How many times `line` names one of `symbols` as a durable transition.
11247	///
11248	/// Blind pass 1 at 5fb1b57 (A05): matching `symbol(` missed a turbofish
11249	/// (`rename::<T>(`) and a function pointer (`let f = fs::rename;`). The symbol
11250	/// is matched on a word boundary and accepted when what follows is a call, a
11251	/// path or turbofish, or the end of a value — never when it is more
11252	/// identifier, so `rename_all` and `append_str` are not renames and appends.
11253	/// Counting occurrences rather than marker spellings keeps one call site worth
11254	/// one site however many spellings would match it.
11255	fn durable_symbol_hits(line: &str, symbols: &[String]) -> usize {
11256	    let identifier = |ch: char| ch.is_alphanumeric() || ch == '_';
11257	    let mut hits = 0;
11258	    for symbol in symbols {
11259	        for (offset, _) in line.match_indices(symbol.as_str()) {
11260	            if line[..offset].chars().next_back().is_some_and(identifier) {
11261	                continue;
11262	            }
11263	            // Blind pass 1 at `2bba9071` (A05): the next character had to BE
11264	            // the call, so `commit_intent (id)` — a space, or a comment
11265	            // between the name and its argument list — named no durable
11266	            // transition. Whitespace and a block comment are not part of the
11267	            // name, so they are stepped over before asking what follows.
11268	            let mut rest = &line[offset + symbol.len()..];
11269	            loop {
11270	                let stepped = rest.trim_start();
11271	                let stepped = match stepped.find("*/") {
11272	                    Some(end) if stepped.starts_with("/*") => &stepped[end + 2..],
11273	                    _ => stepped,
11274	                };
11275	                if stepped.len() == rest.len() {
11276	                    rest = stepped;
11277	                    break;
11278	                }
11279	                rest = stepped;
11280	            }
11281	            let follows = rest.starts_with('(')
11282	                || rest.starts_with("::")
11283	                || rest.starts_with(';')
11284	                || rest.starts_with(',')
11285	                || rest.starts_with(')');
11286	            if follows {
11287	                hits += 1;
11288	            }
11289	        }
11290	    }
11291	    hits
11292	}
