11361	/// The half of the scope claim that reads only the packet, returning the
11362	/// declared surface keyed by path.
11363	///
11364	/// Split from the source-measured half deliberately: `verify_inventory_repo` is
11365	/// exercised against synthetic trees that hold a packet and nothing else, and a
11366	/// check must read only inputs its caller actually has. Measuring source there
11367	/// would either fail on a tree that is not at fault or — the worse outcome —
11368	/// invite a "skip when there is no source" branch, which is how a gate silently
11369	/// degrades into passing everything.
11370	fn verify_crash_boundary_scope_shape(packet: &Packet) -> Result<BTreeMap<&str, usize>> {
11371	    let scope = &packet.crash_boundary_scope;
11372	    anyhow::ensure!(
11373	        !scope.in_scope.is_empty(),
11374	        "crash_boundary_scope.in_scope is empty: §5 exhaustiveness must be claimed over at \
11375	         least one subsystem, or the packet claims nothing"
11376	    );
11377	    anyhow::ensure!(
11378	        !scope.deferred_to.trim().is_empty(),
11379	        "crash_boundary_scope.deferred_to must name who closes the deferral"
11380	    );
11381	    anyhow::ensure!(
11382	        !scope.rationale.trim().is_empty(),
11383	        "crash_boundary_scope.rationale must state why the claim is bounded"
11384	    );
11385	
11386	    // A registered boundary outside every declared subsystem means the packet
11387	    // registers boundaries it has not claimed scope over.
11388	    for row in &packet.crash_boundaries {
11389	        let subsystem = row.boundary.split('/').next().unwrap_or_default();
11390	        anyhow::ensure!(
11391	            scope
11392	                .in_scope
11393	                .iter()
11394	                .any(|entry| entry.subsystem == subsystem),
11395	            "crash boundary {} is outside every declared in-scope subsystem",
11396	            row.boundary
11397	        );
11398	    }
11399	
11400	    let mut declared: BTreeMap<&str, usize> = BTreeMap::new();
11401	    for entry in &scope.in_scope {
11402	        // A blank subsystem would match no boundary while still reading as a
11403	        // claim; a blank path would name no surface. Checked on this side too,
11404	        // not only on `deferred`, so the two halves cannot drift apart.
11405	        anyhow::ensure!(
11406	            !entry.subsystem.trim().is_empty() && !entry.path.trim().is_empty(),
