11431	///
11432	/// Ruling of 2026-08-26 (M17.5 A05): for HAQP-1a, exhaustiveness is claimed
11433	/// over ILRP alone, every other durable transition is deferred to M17.9, and
11434	/// the split is declared in the packet rather than left implicit. Deciding
11435	/// which of the runtime's transitions are *registrable* boundaries is runtime
11436	/// design work; doing it here would either block 1a on Phase 1 or pass by
11437	/// picking a convenient definition, and ADR-0020 §3 forbids improvising
11438	/// qualification semantics.
11439	///
11440	/// What is enforced instead is that the disclosure stays true. A prose scope
11441	/// note rots the first time somebody adds a commit site — which is exactly the
11442	/// defect A05 found in the original unscoped claim — so every durable
11443	/// transition in tracked source must fall inside a declared in-scope subsystem
11444	/// or a declared deferred surface, with counts matching exactly. A new
11445	/// `txn.commit()` anywhere turns the packet red until it is either registered
11446	/// or disclosed.
11447	fn verify_crash_boundary_scope(root: &Utf8Path, packet: &Packet) -> Result<()> {
11448	    let declared = verify_crash_boundary_scope_shape(packet)?;
11449	    let measured = durable_transition_sites(root)?;
11450	    for (path, count) in &measured {
11451	        let Some(expected) = declared.get(path.as_str()) else {
11452	            anyhow::bail!(
11453	                "{path} performs {count} durable transition(s) and is in neither the in-scope \
11454	                 nor the deferred surface: ADR-0020 §5 exhaustiveness cannot be claimed over a \
11455	                 surface the packet has not surveyed. Register its boundaries or disclose it."
11456	            );
11457	        };
11458	        anyhow::ensure!(
11459	            expected == count,
11460	            "{path}: crash_boundary_scope declares {expected} durable transition(s), source has \
11461	             {count}. The disclosure is stale — a durable surface moved under a claim that says \
11462	             it was surveyed."
11463	        );
11464	    }
11465	    for path in declared.keys() {
11466	        anyhow::ensure!(
11467	            measured.contains_key(*path),
11468	            "{path}: crash_boundary_scope declares durable transitions that no longer exist in \
11469	             tracked source"
