354	        assert_eq!(blocks[0].range, SourceRange { start: 1, end: 11 });
355	        assert_eq!(blocks[1].text, "βeta");
356	        assert_eq!(blocks[1].id.as_deref(), Some("second_id"));
357	        assert_eq!(blocks[1].range, SourceRange { start: 16, end: 36 });
358	        assert_eq!(blocks[2].text, "malformed {#bad id!}");
359	        assert_eq!(blocks[2].id, None);
360	        assert_eq!(blocks[2].range, SourceRange { start: 38, end: 58 });
361	    }
362	
363	    #[test]
364	    fn independent_oracle_agrees_with_canonical_parser_and_exposes_divergence() {
365	        let source = "one {#one}\n\ntwo\n  {#two}";
366	        let canonical = paragraph::parse(source);
367	        let oracle = incremental_paragraph_oracle(source);
368	        assert_eq!(oracle, canonical);
369	
370	        let mut diverged = oracle;
371	        diverged[1].range.end -= 1;
372	        assert_ne!(diverged, canonical, "range divergences must be observable");
373	    }
374	}

